import React, { useState, useEffect } from 'react'
import { Form, Col, Row, Button } from 'react-bootstrap'
import { useDispatch, useSelector } from 'react-redux'
import { userRegisterAction } from '../actions/userActions'
import { Link } from 'react-router-dom'
import Message from '../components/Message'
import Loader from '../components/Loader'


function RegisterScreen({ location, history }) {

    // redirect path
    const redirect = location.search ? location.search.split('=')[1] : '/'
    // local states
    const [name, setName] = useState('')
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [confirmPassword, setConfirmPassword] = useState('')
    const [message, setMessage] = useState('')
    const [emailMessage, setEmailMessage] = useState('')

    // handle registe user
    const dispatch = useDispatch()
    const userRegister = useSelector(state => state.userRegister)
    const { userInfo, error, loading } = userRegister
    const submitHandler = (e) => {
        e.preventDefault()
        if (password != confirmPassword) {
            setMessage('Password and confirm password do not match !')
        } else {
            dispatch(userRegisterAction(name, email, password))
            setName('')
            setEmail('')
            setPassword('')
            setConfirmPassword('')
            setMessage('')
        }
    }

    useEffect(() => {
        if (userInfo && userInfo.detail) {
            setEmailMessage(userInfo.detail)
        }
    }, [history, redirect, userInfo])

    return (
        <>
            <h1>sign up</h1>
            {
                loading ? <Loader />
                    : error ? <Message variant='danger' text={error} />
                        : emailMessage ? <Message variant='warning' text={emailMessage} />
                            : message ? <Message variant='danger' text={message} />
                                : <></>
            }
            <Form onSubmit={submitHandler}>
                <Form.Group controlId='name'>
                    <Form.Label>FullName</Form.Label>
                    <Form.Control
                        type='text'
                        placeholder='Enter FullName'
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                    ></Form.Control>
                </Form.Group>

                <Form.Group className='mt-4' controlId='email'>
                    <Form.Label>Email Address</Form.Label>
                    <Form.Control
                        type='email'
                        placeholder='Enter Email'
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                    ></Form.Control>
                </Form.Group>

                <Form.Group className='mt-4' controlId='password'>
                    <Form.Label>Password</Form.Label>
                    <Form.Control
                        type='password'
                        placeholder='Enter Password'
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                    ></Form.Control>
                </Form.Group>

                <Form.Group className='mt-4' controlId='confirmPassword'>
                    <Form.Label>Confirm Password</Form.Label>
                    <Form.Control
                        type='password'
                        placeholder='Enter Confirm Password'
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                    ></Form.Control>
                </Form.Group>

                <Button
                    type='submit'
                    className='my-4 col-4'
                >
                    register
                </Button>
            </Form>

            <Row className="my-4">
                <Col>
                    Have an Account ?

                    <Link to={redirect ? `/login?redirect=${redirect}` : `/login`}>
                        Login
                    </Link>
                </Col>
            </Row>
        </>
    )
}

export default RegisterScreen
